import{c as a,Q as e,j as r,m as s}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-IO缓冲技术","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-IO缓冲技术"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/IO缓冲技术.md","filePath":"综合知识/系统基础/计算机组成/IO缓冲技术.md","lastUpdated":null}'),o={name:"综合知识/系统基础/计算机组成/IO缓冲技术.md"};function n(l,t,d,i,h,c){return e(),r("div",null,[...t[0]||(t[0]=[s('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 单缓冲/双缓冲时间计算公式</li><li>[x] 双缓冲 vs 单缓冲节约时间计算</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="基本参数定义" tabindex="-1">基本参数定义 <a class="header-anchor" href="#基本参数定义" aria-label="Permalink to &quot;基本参数定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><strong>T</strong></td><td>磁盘块读入缓冲区的时间</td></tr><tr><td><strong>M</strong></td><td>缓冲区数据送入用户区的时间</td></tr><tr><td><strong>C</strong></td><td>系统对每个数据块的处理时间</td></tr><tr><td><strong>n</strong></td><td>磁盘块总数</td></tr></tbody></table><h3 id="核心公式" tabindex="-1">核心公式 <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>单缓冲总时间 = nT + nM + C，双缓冲总时间 = (T+M+C) + (n-1)×max(T, M+C)</strong>。双缓冲通过两缓冲区交替工作，让 T 与 (M+C) 并行执行。</p></blockquote><h4 id="单缓冲" tabindex="-1">单缓冲 <a class="header-anchor" href="#单缓冲" aria-label="Permalink to &quot;单缓冲&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总时间 = n×T + n×M + C</span></span></code></pre></div><ul><li>仅有一块缓冲区，读入(T)和送出(M)必须串行</li><li>处理(C)可与下一次读入(T)重叠（前提 C ≤ T，通常情况下成立）</li></ul><h4 id="双缓冲" tabindex="-1">双缓冲 <a class="header-anchor" href="#双缓冲" aria-label="Permalink to &quot;双缓冲&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总时间 = (T+M+C) + (n-1) × max(T, M+C)</span></span></code></pre></div><ul><li>两块缓冲区交替：一块在读出时，另一块在送入用户区+处理</li><li>瓶颈取决于 max(T, M+C)：若 T 大则受限于读取速度，若 M+C 大则受限于传输处理速度</li></ul><h3 id="计算示例" tabindex="-1">计算示例 <a class="header-anchor" href="#计算示例" aria-label="Permalink to &quot;计算示例&quot;">​</a></h3><blockquote><p>T=10μs, M=6μs, C=2μs, n=10</p></blockquote><ul><li><strong>单缓冲</strong>：10×10 + 10×6 + 2 = <strong>162μs</strong></li><li><strong>双缓冲</strong>：(10+6+2) + 9×max(10, 8) = 18 + 90 = <strong>108μs</strong></li><li><strong>节约</strong>：162 - 108 = <strong>54μs</strong></li></ul><h3 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易错点</th><th>正解</th></tr></thead><tbody><tr><td>单缓冲公式写成 n×(T+M+C)</td><td>处理 C 可与下一次读 T 重叠，只需加<strong>最后一次的 C</strong></td></tr><tr><td>双缓冲第一块也有并行</td><td>第一块没有另一缓冲区可交替，必须先 T→M→C 串行</td></tr><tr><td>max(T, M+C) 用错</td><td>是取 T 和 (M+C) 的最大值，不是 T+M 也不是单独取</td></tr></tbody></table>',18)])])}const b=a(o,[["render",n]]);export{p as __pageData,b as default};
